interface Input { readonly id: string; readonly completed: boolean }
export class Host {
  readonly #accepted: Array<Input> = [];
  constructor(private readonly lifetimeLimit: number) {}
  submit(id: string): boolean {
    if (this.#accepted.length >= this.lifetimeLimit) return false;
    this.#accepted.push({ id, completed: false });
    return true;
  }
  complete(id: string): void {
    const index = this.#accepted.findIndex((input) => input.id === id);
    const input = this.#accepted[index];
    if (input !== undefined) this.#accepted[index] = { ...input, completed: true };
  }
  list(): ReadonlyArray<Input> { return this.#accepted.map((input) => ({ ...input })); }
}

