export interface Session {
  readonly cursor: number;
  /** Rejects if no pong arrives within timeoutMs. */
  ping(options: { readonly timeoutMs: number }): Promise<{ readonly cursor: number }>;
  reconnect(): Promise<void>;
  /** Applies all durable events after the supplied cursor and advances cursor. */
  replayAfter(cursor: number): Promise<void>;
}
/** The session owner runs this every five seconds until disposed. */
export const heartbeat = async (session: Session): Promise<void> => {
  try {
    const pong = await session.ping({ timeoutMs: 2_500 });
    if (pong.cursor !== session.cursor) await session.replayAfter(session.cursor);
  } catch {
    await session.reconnect();
    await session.replayAfter(session.cursor);
  }
};

import { notify, type Socket } from "./socket.ts";
export class EventLog {
  readonly #events: Array<string> = [];
  publish(event: string, sockets: ReadonlyArray<Socket>): void {
    this.#events.push(event);
    for (const socket of sockets) notify(socket, event);
  }
  pong() { return { cursor: this.#events.length }; }
  replayAfter(cursor: number) { return this.#events.slice(cursor); }
}

export interface Socket {
  send(event: string): void;
  close(code: number, reason: string): void;
}
export const notify = (socket: Socket, event: string): void => {
  try {
    socket.send(event);
  } catch {
    socket.close(1011, "Notification failed");
  }
};

