import { pendingRecipients } from "./store.ts";
export interface Storage {
  all(sql: string): Promise<ReadonlyArray<{ readonly recipient: string }>>;
  /** Durably enrolls this recipient, then marks its outstanding rows as scheduled. */
  enroll(recipient: string): Promise<void>;
}
/** On startup and after writes. The scheduler has no other legacy-recipient discovery. */
export const reconcile = async (storage: Storage): Promise<void> => {
  for (const row of await storage.all(pendingRecipients)) await storage.enroll(row.recipient);
};

export const migrations = [
  "CREATE TABLE outbox (id TEXT PRIMARY KEY, recipient TEXT NOT NULL, payload TEXT NOT NULL, delivered_at INTEGER)",
];
export const pendingRecipients = "SELECT DISTINCT recipient FROM outbox WHERE delivered_at IS NULL";
export const insert = "INSERT INTO outbox (id, recipient, payload) VALUES (?, ?, ?)";

import { pendingRecipients } from "./store.ts";
export interface Storage {
  all(sql: string): Promise<ReadonlyArray<{ readonly recipient: string }>>;
