export const reconcile = async (storage: Storage): Promise<void> => {
  for (const row of await storage.all(pendingRecipients)) await storage.enroll(row.recipient);
};

export const migrations = [
  "CREATE TABLE outbox (id TEXT PRIMARY KEY, recipient TEXT NOT NULL, payload TEXT NOT NULL, delivered_at INTEGER)",
  "ALTER TABLE outbox ADD COLUMN scheduled_at INTEGER DEFAULT 0",
];
export const pendingRecipients = "SELECT DISTINCT recipient FROM outbox WHERE delivered_at IS NULL AND scheduled_at IS NULL";
export const insert = "INSERT INTO outbox (id, recipient, payload, scheduled_at) VALUES (?, ?, ?, NULL)";
